private static boolean dfs(int current, int target, int[][] paths, boolean[] visited) {
    if (current == target) {
        return true;
    }
    visited[current] = true;
    for (int[] path : paths) {
        if ((path[0] == current && !visited[path[1]]) || (path[1] == current && !visited[path[0]])) {
            if (dfs(path[0] == current ? path[1] : path[0], target, paths, visited)) {
                return true;
            }
        }
    }
    return false;
}

public static String appx(String word1, String word2) {
    int commonLetters = 0;
    int length1 = word1.length();
    int length2 = word2.length();
    boolean[] visited = new boolean[length2];

    for (int i = 0; i < length1; i++) {
        char c1 = word1.charAt(i);
        for (int j = 0; j < length2; j++) {
            if (!visited[j] && c1 == word2.charAt(j)) {
                commonLetters++;
                visited[j] = true;
                break;
            }
        }
    }

    int gcd = gcd(commonLetters, length1 + length2);
    return "appx(" + word1 + ", " + word2 + ") = " + (commonLetters / gcd) + "/" + ((length1 + length2) / gcd);
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

