public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> result = new ArrayList<>();
        if (low > high) {
            return result;
        }
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i <= 9; i++) {
            queue.offer(i);
        }
        while (!queue.isEmpty()) {
            int num = queue.poll();
            if (num >= low && num <= high) {
                result.add(num);
            }
            if (num == 0 || num > high) {
                continue;
            }
            int lastDigit = num % 10;
            if (lastDigit > 0) {
                queue.offer(num * 10 + lastDigit - 1);
            }
            if (lastDigit < 9) {
                queue.offer(num * 10 + lastDigit + 1);
            }
        }
        result.sort(Integer::compareTo);
        return result;
    }

public static int countDigitOne(int n) {
