    for (long factor = 1; factor <= n; factor *= 10) {
        long a = n / (factor * 10);
        long b = n % factor;
        long cur = n / factor % 10;
        if (cur == 0) {
            count += a * factor;
        } else if (cur == 1) {
            count += a * factor + b + 1;
        } else {
            count += (a + 1) * factor;
        }
    }
    return count;
}

