}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    return permute(A, 0);
}

private static int permute(int[] A, int start) {
    if (start == A.length - 1) return 1;
    int count = 0;
    for (int i = start; i < A.length; i++) {
        if (isPerfectSquare(A[start] + A[i])) {
            swap(A, start, i);
            count += permute(A, start + 1);
            swap(A, start, i); // backtrack
        }
    }
    return count;
}

private static boolean isPerfectSquare(int num) {
    int sqrt = (int) Math.sqrt(num);
    return sqrt * sqrt == num;
}

private static void swap(int[] A, int i, int j) {
    int temp = A[i];
    A[i] = A[j];
    A[j] = temp;
}

public static int largestRectangleArea(int[] heights) {
