    for (int i = 0; i < n; i++) {
        int minHeight = Integer.MAX_VALUE;
        for (int j = i; j >= 0; j--) {
            minHeight = Math.min(minHeight, heights[j]);
            int width = i - j + 1;
            int area = minHeight * width;
            maxArea = Math.max(maxArea, area);
        }
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int row = 0, col = 0, d = 1;
    for (int i = 0; i < result.length; i++) {
        result[i] = mat[row][col];
        row += d;
        col -= d;
        if (row >= m) {
            row = m - 1;
            col += 2;
            d = -d;
        }
        if (col >= n) {
            col = n - 1;
            row += 2;
            d = -d;
        }
        if (row < 0) {
            row = 0;
            d = -d;
        }
        if (col < 0) {
            col = 0;
            d = -d;
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int length = digits.length;

    // Start from the second last digit and move towards the first digit
    for (int i = length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            // Find the smallest digit on the right side of digits[i] but greater than digits[i]
            int minIndex = i + 1;
            for (int j = i + 2; j < length; j++) {
                if (digits[j] > digits[i] && digits[j] < digits[minIndex]) {
                    minIndex = j;
                }
            }

            // Swap the found digit with digits[i]
            char temp = digits[i];
            digits[i] = digits[minIndex];
            digits[minIndex] = temp;

            // Sort the digits after the current position
            Arrays.sort(digits, i + 1, length);

            // Convert the digits back to an integer
            return Integer.parseInt(new String(digits));
        }
    }

    // If no such digit is found, return -1
    return -1;
}

public static List<String> centerSymmetricNumbers(int n) {
        List<String> result = new ArrayList<>();
        if (n == 0) {
            return result;
        }
        if (n == 1) {
            result.add("0");
            result.add("1");
            result.add("8");
