        }
        helper(result, new char[n], 0, n - 1);
        return result;
    }

private static void helper(List<String> result, char[] current, int left, int right) {
        if (left > right) {
            result.add(new String(current));
            return;
        }
        if (left == right) {
            current[left] = '0';
            result.add(new String(current));
            current[left] = '1';
            result.add(new String(current));
            current[left] = '8';
            return;
        }
        if (left == right - 1) {
            current[left] = '0';
            current[right] = '0';
            result.add(new String(current));
            current[left] = '1';
            current[right] = '1';
            result.add(new String(current));
            current[left] = '6';
            current[right] = '9';
            result.add(new String(current));
            current[left] = '8';
            current[right] = '8';
            result.add(new String(current));
            current[left] = '9';
            current[right] = '6';
            result.add(new String(current));
            return;
        }
        char[] options = {'0', '1', '6', '8', '9'};
        for (char option : options) {
            if (left == 0 && option == '0') {
                continue;
            }
            current[left] = option;
            current[right] = getSymmetric(option);
            helper(result, current, left + 1, right - 1);
        }
    }

private static char getSymmetric(char c) {
        if (c == '6') {
            return '9';
        } else if (c == '9') {
            return '6';
        } else {
            return c;
        }
    }

